class Weapon:
    """
    Base class for all weapons in CyberArena
    """
    def __init__(self, name, damage, weapon_range, ammo=0, reload_time=1.0):
        self.name = name
        self.damage = damage
        self.range = weapon_range
        self.ammo = ammo
        self.reload_time = reload_time
        self.next_shot_time = 0.0

    def can_fire(self):
        return time.time() >= self.next_shot_time and self.ammo > 0

    def fire(self):
        if self.can_fire():
            self.next_shot_time = time.time() + self.reload_time
            self.ammo -= 1
            return True
        return False

class Robot:
    """
