        self.strategy = 'default'
        self.role = random.choice(['attacker', 'defender', 'support'])

    def move(self, dx, dy):
        self.x += dx
        self.y += dy

    def take_damage(self, amount):
        self.health -= amount
        if self.health <= 0:
            self.die()

    def die(self):
        print(f'{self.name} from {self.team} has been destroyed.')

    def select_target(self, enemies):
        if self.role == 'attacker':
            return min(enemies, key=lambda e: self.distance(e))
        elif self.role == 'defender':
            return max(enemies, key=lambda e: self.distance(e))
        else:
            return random.choice(enemies)

    def distance(self, other):
        return ((self.x - other.x)**2 + (self.y - other.y)**2)**0.5

class Team:
    """
