    def load_data(self):
        """Load budget data from a JSON file."""
        if os.path.exists(self.filename):
            try:
                with open(self.filename, 'r') as file:
                    self.data = json.load(file)
            except json.JSONDecodeError:
                # Handle empty or corrupted file
                self.data = {'users': {}, 'categories': {}}
        else:
            self.data = {'users': {}, 'categories': {}}

    def save_data(self):
        """Save the current budget data to a JSON file."""
        with open(self.filename, 'w') as file:
            json.dump(self.data, file, indent=4)

    def add_user(self, username, initial_budget=1000.0):
        """Add a new user to the budget system with an optional initial budget."""
        if username in self.data['users']:
            return f'User {username} already exists.'
        self.data['users'][username] = {
            'budget': initial_budget,
            'expenses': {},
            'contributions': 0.0
        }
        self.save_data()
        return f'User {username} added successfully with initial budget: ${initial_budget:.2f}.'

    def input_expense(self, username, category, amount):
        """Record an expense for a specific user and category."""
        if username not in self.data['users']:
            return f'User {username} does not exist.'
        if category not in self.data['categories']:
            self.data['categories'][category] = 0.0
        self.data['users'][username]['expenses'].setdefault(category, 0.0)
        self.data['users'][username]['expenses'][category] += amount
        self.data['categories'][category] += amount
        self.save_data()
        return f'Expense of ${amount:.2f} recorded for {username} in category: {category}.'

    def set_category_limit(self, category, limit):
        """Set a budget limit for a specific category."""
        self.data['categories'][category] = limit
        self.save_data()
        return f'Category limit for {category} set to: ${limit:.2f}.'

    def get_user_budget_status(self, username):
        """Get the budget status for a specific user."""
        if username not in self.data['users']:
            return f'User {username} does not exist.'
        user_data = self.data['users'][username]
        total_expenses = sum(user_data['expenses'].values())
        remaining_budget = user_data['budget'] - total_expenses
        return {
            'username': username,
            'budget': user_data['budget'],
            'expenses': user_data['expenses'],
            'total_expenses': total_expenses,
            'remaining_budget': remaining_budget
        }

    def get_group_dashboard(self):
        """Generate a summary of the group's financial status."""
        total_group_budget = 0.0
        total_group_spent = 0.0
        under_budget_users = []
