        """Retrieve a specific budget by ID."""
        for budget in self.budgets:
            if budget.budget_id == budget_id:
                return budget
        return None

    def get_budgets(self):
        """Get all budgets the user is part of."""
        return self.budgets

# Define a shared budget class
class SharedBudget:
    def __init__(self, budget_id: str, name: str, owner_id: str, total_income: float = 0.0):
        self.budget_id = budget_id
        self.name = name
        self.owner_id = owner_id
        self.total_income = total_income
        self.expenses = []  # List of expenses in this budget
        self.categories = {}  # Dictionary of categories and their budgets
        self.users = {}  # Dictionary of users with their permission levels
        self.budget_goals = []  # List of budget goals (e.g., savings targets)
        self.notifications = []  # List of notifications related to this budget

    def add_user(self, user_id: str, permission: PermissionLevel):
        """Add a user to the budget with specified permission level."""
        self.users[user_id] = permission

    def remove_user(self, user_id: str):
        """Remove a user from the budget."""
        if user_id in self.users:
            del self.users[user_id]

    def update_permission(self, user_id: str, new_permission: PermissionLevel):
        """Update a user's permission level in the budget."""
        if user_id in self.users:
            self.users[user_id] = new_permission

    def add_expense(self, expense: dict):
        """Add an expense to the budget."""
        self.expenses.append(expense)

    def add_income(self, income: dict):
        """Add income to the budget."""
        self.total_income += income['amount']
        # Add to budget's financial data

    def add_category(self, category_name: str, category_budget: float):
        """Add a new category with a budget to the shared budget."""
        self.categories[category_name] = category_budget

    def set_budget_goal(self, goal_name: str, target_amount: float, deadline: datetime.date):
        """Set a budget goal with a name, target amount, and deadline."""
        self.budget_goals.append({
            'name': goal_name,
            'target_amount': target_amount,
            'deadline': deadline,
            'current_amount': 0.0
        })

    def update_budget_goal(self, goal_name: str, amount: float):
        """Update the current amount for a budget goal."""
        for goal in self.budget_goals:
            if goal['name'] == goal_name:
                goal['current_amount'] += amount
                # Check if target is reached
                if goal['current_amount'] >= goal['target_amount']:
                    self.notifications.append(f"Budget goal '{goal_name}' has been reached!")
                break

    def check_budget_health(self):
        """Check if the budget is on track based on spending and income."""
        total_spent = sum(expense['amount'] for expense in self.expenses)
        if total_spent > self.total_income * 0.9:
            self.notifications.append("Warning: Spending is over 90% of income. Consider adjusting your budget.")
        elif total_spent > self.total_income * 0.75:
            self.notifications.append("Notice: Spending is over 75% of income. Consider reviewing expenses.")

# Define a transaction class for expenses and income
class Transaction:
    def __init__(self, amount: float, description: str, category: str, date: datetime.date):
        self.transaction_id = str(uuid.uuid4())
        self.amount = amount
        self.description = description
        self.category = category
        self.date = date

    def to_dict(self):
        """Convert the transaction to a dictionary for storage."""
        return {
            "transaction_id": self.transaction_id,
            "amount": self.amount,
            "description": self.description,
            "category": self.category,
            "date": self.date.isoformat()
        }

    @staticmethod
    def from_dict(data: dict):
        """Create a transaction from a dictionary."""
        return Transaction(
            amount=float(data["amount"]),
            description=data["description"],
            category=data["category"],
            date=datetime.date.fromisoformat(data["date"])
        )

