        """Delete a shared budget if the requesting user is an admin."""
        if budget_id in self.budgets:
            budget = self.budgets[budget_id]
            if budget.owner_id == admin_user_id or budget.users.get(admin_user_id) == PermissionLevel.ADMIN:
                del self.budgets[budget_id]
                # Remove the budget from all users' budgets list
                for user in self.users.values():
                    if budget_id in [b.budget_id for b in user.budgets]:
                        user.budgets = [b for b in user.budgets if b.budget_id != budget_id]
            else:
                self.notifications.append(f"User {admin_user_id} is not an admin of budget {budget_id}.")

