            # Add the budget to the user's list of budgets
            user = self.users.get(user_id)
            if user and self.budgets[budget_id] not in user.budgets:
                user.budgets.append(self.budgets[budget_id])

    def remove_user_from_budget(self, budget_id: str, user_id: str):
        """Remove a user from a shared budget."""
        if budget_id in self.budgets:
            self.budgets[budget_id].remove_user(user_id)
            # Remove the budget from the user's list of budgets
            user = self.users.get(user_id)
            if user:
                user.budgets = [b for b in user.budgets if b.budget_id != budget_id]

