        """Update a user's permission level in a shared budget."""
        if budget_id in self.budgets:
            self.budgets[budget_id].update_permission(user_id, new_permission)

    def add_transaction_to_budget(self, budget_id: str, user_id: str, amount: float, 
                                  description: str, category: str, date: datetime.date):
        """Add a transaction (expense or income) to a shared budget."""
        if budget_id in self.budgets:
            budget = self.budgets[budget_id]
            if budget.users.get(user_id) in [PermissionLevel.EDIT, PermissionLevel.ADMIN]:
                transaction = Transaction(amount, description, category, date)
                if amount > 0:
                    # Income
                    budget.add_income(transaction.to_dict())
                else:
                    # Expense
                    budget.add_expense(transaction.to_dict())
                    # Check if this expense exceeds a category budget
                    if category in budget.categories:
                        category_budget = budget.categories[category]
                        category_spent = sum(expense['amount'] for expense in budget.expenses 
                                             if expense['category'] == category)
                        if category_spent > category_budget:
                            budget.notifications.append(
