        """Generate a visualization (chart) for a shared budget's spending breakdown."""
        if budget_id not in self.budgets:
            return "Budget not found."

        budget = self.budgets[budget_id]
        # Calculate total spending per category
        category_spending = {}
        for expense in budget.expenses:
            category = expense["category"]
            amount = expense["amount"]
            if category in category_spending:
                category_spending[category] += amount
            else:
                category_spending[category] = amount

        if not category_spending:
            return "No expenses found for visualization."

        categories = list(category_spending.keys())
        amounts = list(category_spending.values())

        # Select visualization template
        template = next((tpl for tpl in self.visualization_templates 
                        if tpl["name"] == visualization_type), None)

        if template is None:
            return f"Visualization type '{visualization_type}' not recognized."

        # Generate the visualization
        if template["type"] == "pie":
