            plt.pie(amounts, labels=categories, autopct='%1.1f%%')
            plt.title(f"Spending Breakdown for {budget.name}")
        elif template["type"] == "bar":
            plt.figure(figsize=(10, 6))
            plt.bar(categories, amounts)
            plt.xlabel("Category")
            plt.ylabel("Amount")
            plt.title(f"Spending Breakdown for {budget.name}")
        elif template["type"] == "line":
            # For line chart, we'll need to sort by date
            dates = []
            for expense in budget.expenses:
                if expense["date"] not in dates:
                    dates.append(expense["date"])
            dates.sort()

            # Get spending per date
            date_spending = {date: 0 for date in dates}
            for expense in budget.expenses:
                date_spending[expense["date"]] += expense["amount"]

