            plt.plot(dates, [date_spending[date] for date in dates])
            plt.xlabel("Date")
            plt.ylabel("Amount")
            plt.title(f"Spending Over Time for {budget.name}")
            plt.xticks(rotation=45)

        plt.tight_layout()
