        self.goals.append({'goal_name': goal_name, 'target_amount': target_amount, 'deadline': deadline, 'current_amount': 0})

    def update_entry(self, entry_id, new_amount=None, new_category=None, new_description=None):
        for entry in self.entries:
            if entry.entry_id == entry_id:
                if new_amount:
                    entry.amount = new_amount
                if new_category:
                    entry.category = new_category
                if new_description:
                    entry.description = new_description
                break

    def delete_entry(self, entry_id):
