        balance = total_income - total_expense
        return {
            'total_income': total_income,
            'total_expense': total_expense,
            'balance': balance,
            'category_breakdown': self._get_category_breakdown()
        }

    def _get_category_breakdown(self):
        income_breakdown = defaultdict(float)
        expense_breakdown = defaultdict(float)
        for entry in self.entries:
            if entry.is_income:
                income_breakdown[entry.category] += entry.amount
            else:
                expense_breakdown[entry.category] += entry.amount
        return {
            'income': dict(income_breakdown),
            'expense': dict(expense_breakdown)
        }

